CSS:
html{color-scheme:light}body{margin:0}img{max-width:100%}[hidden]{display:none!important}

/* 컨셉: 딸기우유 스티커 도감 — 크림 핑크 종이 위 땡땡이, 진한 베리색 잉크 테두리 스티커.
   제목·버튼 주아체 / 긴 글 고운돋움 */
:root{
  --paper:#FFFFFF; --soft:#FFF3F6; --surface:#FFFFFF; --ink:#4A2633; --muted:#86606D; --line:#F2E1E6;
  --p:#2E7A6B; --p-ink:#FFFFFF; --p-soft:#EAF5F1; --p-line:#CBE5DC; --p-deep:#1F4F46;
  --brand:#C93D67; --brand-ink:#FFFFFF; --brand-soft:#FFE3EB; --sun:#FF8FAB; --sun-ink:#4A2231;
  --stage:#FFE6EC; --stage2:#FFF5CF; --star:#FFC531; --edge:#4A2633;
  --t-obs:#9EE6C4; --t-spa:#A8D3FF; --t-lan:#FFC9A0; --t-num:#FFE680;
  --t-cre:#C6B8FF; --t-foc:#97E3E0; --t-mem:#FF9FBA; --t-sol:#C8EB95;
  --f-head:"Bagel Fat One","Jua","Apple SD Gothic Neo",sans-serif;
  --f-kid:"Jua","Apple SD Gothic Neo","Malgun Gothic",sans-serif;
  --f-body:"Gowun Dodum","Apple SD Gothic Neo","Malgun Gothic",sans-serif;
  --pop:4px 4px 0 var(--edge);
  --bg:var(--paper); --f-display:var(--f-kid); --shadow:none; --r:18px;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --paper:#22161B; --soft:#2E1E25; --p:#7CC9B6; --p-ink:#10261F; --p-soft:#1C2E29; --p-line:#2E4A42; --p-deep:#BDE6DA; --surface:#38222D; --ink:#FFEAF0; --muted:#D9AEBD; --line:#4E3241;
  --brand:#FF9DB8; --brand-ink:#2A1820; --brand-soft:#4A2A38; --stage:#40242F; --stage2:#3D3424; --edge:#170A10; color-scheme:dark}}
:root[data-theme="dark"]{
  --paper:#22161B; --soft:#2E1E25; --p:#7CC9B6; --p-ink:#10261F; --p-soft:#1C2E29; --p-line:#2E4A42; --p-deep:#BDE6DA; --surface:#38222D; --ink:#FFEAF0; --muted:#D9AEBD; --line:#4E3241;
  --brand:#FF9DB8; --brand-ink:#2A1820; --brand-soft:#4A2A38; --stage:#40242F; --stage2:#3D3424; --edge:#170A10; color-scheme:dark}
*{box-sizing:border-box}
body{background:var(--paper);color:var(--ink);font-family:var(--f-body);font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word;-webkit-text-size-adjust:100%}
h1,h2,h3{line-height:1.3;text-wrap:balance;margin:0}
p{margin:0}
button{font:inherit;color:inherit;cursor:pointer}
a{color:var(--brand)}
:focus-visible{outline:3px solid var(--brand);outline-offset:3px;border-radius:8px}
.wrap{max-width:1120px;margin:0 auto;padding-inline:20px}
.narrow{max-width:680px}
.kid{font-family:var(--f-kid);font-weight:400}

/* header */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:color-mix(in srgb,var(--paper) 90%,transparent);backdrop-filter:blur(10px)}
.top .wrap{display:flex;align-items:center;justify-content:space-between;height:64px;gap:12px}
.logo{display:flex;align-items:center;gap:8px;font-family:var(--f-head);font-size:21px;color:var(--ink);background:none;border:0;padding:0}
.logo svg{width:34px;height:34px}
.top nav{display:flex;gap:2px}
.top nav button{background:none;border:0;padding:8px 12px;border-radius:12px;font-weight:600;font-size:15px;color:var(--muted);min-height:44px}
.top nav button:hover{color:var(--ink)}
@media (max-width:640px){.top nav .hide-m{display:none}}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:16px;font-weight:700;min-height:52px;padding:0 24px;font-size:17px;text-decoration:none;transition:transform .1s,box-shadow .1s}
.btn-main{background:var(--brand);color:var(--brand-ink);box-shadow:0 5px 0 color-mix(in srgb,var(--brand) 55%,#000)}
.btn-main:active{box-shadow:0 1px 0 color-mix(in srgb,var(--brand) 55%,#000);transform:translateY(4px)}
.btn-sun{background:var(--sun);color:var(--sun-ink);border:2.5px solid var(--edge);box-shadow:var(--pop);font-family:var(--f-kid);font-weight:400;font-size:20px}
.btn-sun:active{transform:translate(3px,3px);box-shadow:1px 1px 0 var(--edge)}
.btn-big{min-height:62px;font-size:20px;padding:0 34px}
.btn-ghost{background:var(--surface);color:var(--ink);border:1.5px solid var(--line)}
.btn-block{width:100%}

/* hero */
.hero{position:relative;isolation:isolate;display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:center;padding-block:40px 20px}
.hero h1{font-family:var(--f-head);font-weight:400;font-size:clamp(46px,8.4vw,88px);line-height:1.08;letter-spacing:-.02em}
.hero .sub{font-size:clamp(18px,2.4vw,21px);font-weight:700;margin-top:22px}
.hero .sub2{color:var(--muted);margin-top:4px;font-size:17px}
.hero .cta{margin-top:30px;display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.hero .note{font-size:14px;color:var(--muted)}
.field{position:relative;aspect-ratio:1/1.04;width:100%;max-width:100%}
.stk{position:absolute;width:24%;display:flex;flex-direction:column;align-items:center;transform:rotate(var(--r));border:0;background:none;padding:0;animation:land .55s cubic-bezier(.3,1.5,.5,1) both;animation-delay:var(--d)}
.stk .die{width:100%;aspect-ratio:1/1;border-radius:50%;background:var(--c);border:3px solid var(--edge);box-shadow:var(--pop);display:flex;align-items:center;justify-content:center;outline:7px solid var(--surface);outline-offset:-1px}
.stk .die svg{width:84%;height:auto}
.stk .lb{margin-top:10px;background:var(--surface);border:2px solid var(--edge);border-radius:999px;padding:2px 12px;font-family:var(--f-kid);font-size:clamp(14px,1.6vw,17px);white-space:nowrap}
.stk.wig{animation:wig .5s}
@keyframes land{from{transform:rotate(var(--r)) scale(.4)}to{transform:rotate(var(--r)) scale(1)}}
@keyframes wig{0%,100%{transform:rotate(var(--r))}25%{transform:rotate(calc(var(--r) - 12deg)) scale(1.08)}75%{transform:rotate(calc(var(--r) + 10deg)) scale(1.08)}}
@media (max-width:860px){
  .hero{grid-template-columns:1fr;padding-block:20px 8px}
  .field{aspect-ratio:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:16px 10px;order:2;margin-top:8px;max-width:520px}
  .stk{position:static;width:auto}
  .stk .die{outline-width:4px;border-width:2.5px;box-shadow:3px 3px 0 var(--edge)}
  .stk .lb{font-size:13px;padding:1px 8px;border-width:1.5px}
}

.qmark{position:absolute;left:38%;top:36%;width:26%;aspect-ratio:1/1;display:flex;align-items:center;justify-content:center;background:var(--sun);border:3px solid var(--edge);border-radius:28px;box-shadow:var(--pop);font-family:var(--f-kid);font-size:clamp(56px,7vw,92px);color:var(--sun-ink);transform:rotate(-4deg)}
@media (max-width:860px){.qmark{display:none}}
#app{overflow-x:clip}
.hero::before{content:"";position:absolute;z-index:-1;top:-20px;bottom:0;left:calc(50% - 50vw);right:calc(50% - 50vw);background:linear-gradient(180deg,var(--soft),var(--paper))}
/* ticket strip */
.ticket{display:grid;grid-template-columns:repeat(4,1fr);background:var(--surface);border:2.5px solid var(--edge);border-radius:20px;margin-block:28px 0;position:relative}
.ticket>div{padding:18px 20px;min-width:0}
.ticket>div+div{border-left:2.5px dashed var(--line)}
.ticket b{display:block;font-family:var(--f-kid);font-weight:400;font-size:24px;line-height:1.2}
.ticket span{font-size:14px;color:var(--muted)}
@media (max-width:720px){.ticket{grid-template-columns:1fr 1fr}.ticket>div:nth-child(3){border-left:0}.ticket>div:nth-child(n+3){border-top:2.5px dashed var(--line)}}

/* sections */
section.blk{padding-block:80px 0}
.blk h2{font-family:var(--f-head);font-weight:400;font-size:clamp(30px,4.6vw,46px);letter-spacing:-.01em}
.blk .lead{color:var(--muted);margin-top:12px;max-width:58ch;font-size:17px}
.eyebrow{font-size:14px;font-weight:700;color:var(--brand)}

/* try (console) */
.try{display:grid;grid-template-columns:260px 1fr;gap:24px;margin-top:36px;align-items:start}
.try-tabs{display:flex;flex-direction:column;gap:10px}
.try-tabs button{text-align:left;background:var(--surface);border:2px solid var(--line);border-radius:16px;padding:12px 16px;font-weight:600;min-height:60px;display:flex;gap:12px;align-items:center;font-size:15px}
.try-tabs button[aria-selected="true"]{border-color:var(--edge);box-shadow:3px 3px 0 var(--edge)}
.try-tabs .dot{width:16px;height:16px;border-radius:50%;border:2px solid var(--edge);flex:none}
.console{background:var(--edge);border-radius:34px;padding:14px;box-shadow:0 14px 30px rgba(38,36,90,.18)}
@media (max-width:760px){.try{grid-template-columns:1fr}.try-tabs{flex-direction:row;overflow-x:auto;padding-bottom:6px}.try-tabs button{flex:1 0 auto;min-height:52px}}

/* stage (kid screen) */
.stage{background:var(--stage);border-radius:24px;padding:20px;min-height:430px;display:flex;flex-direction:column;position:relative;overflow:hidden;font-family:var(--f-kid)}
.stage .q{font-size:clamp(21px,4.8vw,27px);text-align:center;margin-block:6px 16px;line-height:1.35}
.stage .q small{display:block;font-size:15px;color:var(--muted);font-family:var(--f-body);font-weight:600}
.play{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;width:100%}
.grid{display:grid;gap:8px;width:100%;max-width:420px}
.tile{background:var(--surface);border:2.5px solid var(--edge);border-radius:16px;font-size:clamp(26px,7vw,38px);aspect-ratio:1/1;min-height:52px;display:flex;align-items:center;justify-content:center;box-shadow:3px 3px 0 var(--edge);transition:transform .08s,background .2s;font-family:var(--f-kid);padding:0;line-height:1;color:var(--ink)}
.tile:active{transform:translate(2px,2px);box-shadow:1px 1px 0 var(--edge)}
.tile.on{background:var(--brand);color:var(--brand-ink)}
.tile.hit{background:#BDEBCF}
.tile.lit{background:var(--star)}
.opts{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;width:100%;max-width:520px}
.opt{background:var(--surface);border:2.5px solid var(--edge);border-radius:18px;min-height:64px;padding:12px 14px;font-size:clamp(17px,4.2vw,21px);box-shadow:3px 3px 0 var(--edge);font-family:var(--f-kid);display:flex;align-items:center;justify-content:center;text-align:center;line-height:1.3;color:var(--ink)}
.opt:active{transform:translate(2px,2px);box-shadow:1px 1px 0 var(--edge)}
.opt.sel{background:var(--sun);color:var(--sun-ink)}
.opt svg{width:min(100%,110px);height:auto}
.opts.one{grid-template-columns:1fr}
.scene{font-size:clamp(34px,10vw,52px);display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;background:var(--surface);border:2.5px solid var(--edge);border-radius:20px;padding:14px 20px;line-height:1.15}
.scene .arrow{font-size:24px;color:var(--muted)}
.timer{height:10px;background:var(--surface);border:2px solid var(--edge);border-radius:9px;width:100%;max-width:420px;overflow:hidden}
.timer i{display:block;height:100%;background:var(--sun);width:100%;transition:width linear}
.flash{width:min(60vw,210px);aspect-ratio:1/1;background:var(--surface);border-radius:36px;display:flex;align-items:center;justify-content:center;font-size:clamp(70px,22vw,112px);border:3px solid var(--edge);box-shadow:5px 5px 0 var(--edge)}
.reward{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:color-mix(in srgb,var(--stage) 94%,transparent);z-index:5;text-align:center;padding:20px}
.reward .st{font-size:70px;animation:pop .5s cubic-bezier(.3,1.6,.5,1)}
.reward p{font-size:23px}
@keyframes pop{from{transform:scale(.2) rotate(-30deg)}to{transform:none}}

/* test shell */
.testbar{display:flex;align-items:center;gap:12px;margin-block:16px 14px}
.prog{flex:1;height:16px;background:var(--surface);border:2.5px solid var(--edge);border-radius:99px;position:relative}
.prog i{display:block;height:100%;background:var(--sun);border-radius:99px;transition:width .5s}
.prog .walker{position:absolute;top:50%;width:36px;height:36px;transform:translate(-50%,-55%);transition:left .5s}
.testbar .pct{font-weight:700;font-size:14px;color:var(--muted);white-space:nowrap}
.stars-earned{font-family:var(--f-kid);font-size:18px;white-space:nowrap}
.exit{background:none;border:0;color:var(--muted);font-weight:700;min-height:44px;padding:0 6px;font-size:18px}
@media (max-width:420px){.testbar .pct{font-size:12.5px}}

/* parent paper */
.card{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:28px}
@media (max-width:520px){.card{padding:22px}}
.field-row{margin-top:22px}
.field-row>label,.lab{display:block;font-weight:700;margin-bottom:8px}
.hint{font-size:13.5px;color:var(--muted);font-weight:500;margin-left:6px}
input[type=text]{width:100%;font:inherit;font-size:17px;padding:14px 16px;border:1.5px solid var(--line);border-radius:14px;background:var(--paper);color:var(--ink);min-height:54px}
input:focus{outline:none;border-color:var(--brand)}
.seg{display:flex;gap:8px;flex-wrap:wrap}
.pick{border:2px solid var(--line);background:var(--surface);border-radius:999px;padding:0 16px;min-height:48px;font-weight:600;font-size:15px}
.pick[aria-pressed="true"]{background:var(--sun);border-color:var(--edge);color:var(--sun-ink);box-shadow:2px 2px 0 var(--edge)}
.ages{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.ages .pick{border-radius:14px;padding:0;font-family:var(--f-kid);font-weight:400;font-size:18px}
.err{color:#C2412D;font-size:14px;font-weight:700;margin-top:8px}

/* result */
.res-hero{text-align:center;padding-block:36px 8px}
.res-hero .char{width:170px;height:170px;margin:0 auto;border-radius:50%;border:3px solid var(--edge);box-shadow:var(--pop);display:flex;align-items:center;justify-content:center;outline:8px solid var(--surface)}
.res-hero .char svg{width:84%;height:auto}
.res-hero h1{font-family:var(--f-head);font-weight:400;font-size:clamp(30px,6vw,46px);margin-top:16px}
.res-hero h1 em{font-style:normal}
.top3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:28px}
.top3>div{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:18px 20px;min-width:0;display:flex;flex-direction:column}
.top3 .rk{font-size:13px;font-weight:700;color:var(--muted)}
.top3 .nm{font-weight:700;font-size:18px}
.top3 .sc{font-family:var(--f-kid);font-size:44px;line-height:1.1;font-variant-numeric:tabular-nums}
@media (max-width:520px){.top3{grid-template-columns:1fr}.top3>div{flex-direction:row;align-items:center;gap:14px}.top3 .sc{margin-left:auto}}
.two{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}
@media (max-width:820px){.two{grid-template-columns:1fr}}
.bars{display:flex;flex-direction:column;gap:12px}
.bar{display:grid;grid-template-columns:78px 1fr 40px;gap:10px;align-items:center;font-weight:600;font-size:15px}
.bar .tr{height:12px;background:var(--paper);border-radius:9px;overflow:hidden}
.bar .tr i{display:block;height:100%;border-radius:9px}
.bar .v{text-align:right;font-variant-numeric:tabular-nums}
.bar.lock .tr,.bar.lock .v{filter:blur(5px)}
.lockbox{position:relative}
.lockbox .veil{position:absolute;inset:auto 0 0 0;display:flex;justify-content:center;padding:40px 0 22px;background:linear-gradient(transparent,var(--surface) 50%);border-radius:0 0 20px 20px}
.explain h3{font-size:20px}
.explain p{margin-top:10px}
.explain .aha,.aha{margin-top:14px;background:var(--stage2);border-radius:14px;padding:14px 16px;font-weight:600}
.tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}
.tag{background:var(--paper);border-radius:999px;padding:6px 14px;font-size:14.5px;font-weight:600}
.radar text{fill:var(--muted);font-size:12px;font-weight:600;font-family:var(--f-body)}
.radar{width:100%;max-width:340px;display:block;margin:0 auto}
.disc{font-size:13px;color:var(--muted);margin-top:20px;text-align:center}
.lock-list{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.lock-list div{background:var(--paper);border-radius:12px;padding:10px 12px;font-weight:600;font-size:14.5px}
@media (max-width:520px){.lock-list{grid-template-columns:1fr}}
.products{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}
.prod{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:22px;display:flex;flex-direction:column;gap:10px;min-width:0}
.prod.hl{border:2.5px solid var(--edge);box-shadow:var(--pop)}
.prod h3{font-size:18px}
.prod ul{margin:0;padding-left:18px;color:var(--muted);font-size:14.5px}
.prod .soon{margin-top:auto;font-size:13.5px;color:var(--muted);font-weight:700}
@media (max-width:820px){.products{grid-template-columns:1fr}}

/* mission */
.mission{background:var(--stage2);border:2.5px solid var(--edge);box-shadow:var(--pop);border-radius:26px;padding:26px;display:grid;grid-template-columns:auto 1fr;gap:22px;align-items:center}
.mission .ico{width:90px;height:90px}
.mission h3{font-family:var(--f-kid);font-weight:400;font-size:27px}
.mission p{margin-top:6px;font-size:17px}
.mission .row{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}
@media (max-width:520px){.mission{grid-template-columns:1fr;text-align:center}.mission .ico{margin:0 auto}.mission .row{justify-content:center}}
.badges{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:12px;margin-top:14px}
.badge{text-align:center;font-weight:700;font-size:13.5px}
.badge svg{width:64px;height:64px;display:block;margin:0 auto 6px;border-radius:50%;border:2.5px solid var(--edge);background:var(--surface)}
.badge.off{opacity:.35;filter:grayscale(1)}

/* dashboard */
.dash{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px}
.stat{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:18px 20px;min-width:0}
.stat .k{font-size:13.5px;color:var(--muted);font-weight:600}
.stat .v{font-family:var(--f-kid);font-size:32px;margin-top:2px;font-variant-numeric:tabular-nums}
@media (max-width:620px){.dash{grid-template-columns:1fr 1fr}.dash .stat:last-child{grid-column:span 2}}
.delta{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}
.delta div{background:var(--paper);border-radius:14px;padding:12px;font-weight:600;text-align:center;font-size:14px}
.delta b{display:block;font-family:var(--f-kid);font-weight:400;font-size:26px}
.up{color:#1E8A55}.down{color:var(--muted)}
@media (max-width:520px){.delta{grid-template-columns:repeat(2,1fr)}}
.history{width:100%;border-collapse:collapse;font-size:14.5px;font-variant-numeric:tabular-nums}
.history th,.history td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:center;white-space:nowrap}
.scroll{overflow-x:auto}

/* share */
.share-img{width:100%;max-width:360px;border-radius:22px;display:block;margin:0 auto;border:2.5px solid var(--edge);box-shadow:var(--pop)}
.check{display:flex;gap:10px;align-items:center;font-weight:600;min-height:44px;justify-content:center}
.check input{width:22px;height:22px}

/* areas (sticker book page) */
.areas{display:grid;grid-template-columns:repeat(4,1fr);gap:40px 20px;margin-top:44px;background:var(--surface);border-radius:28px;padding:40px 28px;border:1px solid var(--line)}
.area{text-align:center;min-width:0}
.area .die{width:min(120px,80%);aspect-ratio:1/1;margin:0 auto;border-radius:50%;border:3px solid var(--edge);box-shadow:var(--pop);display:flex;align-items:center;justify-content:center;outline:6px solid var(--surface);transform:rotate(var(--r))}
.area .die svg{width:84%;height:auto}
.area h3{font-family:var(--f-kid);font-weight:400;font-size:21px;margin-top:16px}
.area p{font-size:14px;color:var(--muted)}
@media (max-width:820px){.areas{grid-template-columns:repeat(2,1fr);padding:30px 16px;gap:32px 12px}}

/* report preview */
.sheet{display:grid;grid-template-columns:.9fr 1.1fr;gap:0;margin-top:36px;background:var(--surface);border:1px solid var(--line);border-radius:28px;overflow:hidden}
.sheet .kidside{background:var(--stage);padding:32px 24px;text-align:center;border-right:1px solid var(--line)}
